import mapboxgl from 'mapbox-gl';
import {  NavigationControl } from 'react-map-gl';
import Map, { Layer, Marker, Popup, Source } from 'react-map-gl';
import { Suspense, useCallback, useState, useRef, useEffect, useMemo } from 'react';
import { csvToJsonArray } from '../../../lib/NJSCore/Core/NData'
import Controller from './Controller/index';

import BInterpolation from './Component/BInterpolation';

import 'mapbox-gl/dist/mapbox-gl.css';
import styles from './style.module.css';

const App = () => {
  const mapRef = useRef();

  const [dataElection, setDataElection] = useState(null);
  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await fetch(process.env.PUBLIC_URL + '/static/dataDummyReady/presidential_election_county_summary_bead.csv');
        if (!response.ok) {
          throw new Error('Failed to load csv data');
        }

        const csvText = await response.text();
        const result = csvToJsonArray(csvText)
        // console.log(result)
        setDataElection(result)
      } catch (error) {
        console.error('Error fetching GeoJSON:', error);
      }
    };

    fetchData();
  }, []);

  const interpolateColor = useCallback((input) => {
    if (input < 0 || input > 1) {
      throw new Error('Input must be between 0 and 1.')
    }
    const red = Math.round(255 * (1 - input))
    const blue = Math.round(255 * input)
    return [red, 0, blue]
  }, [])

  const getLocPctServed = useCallback((geoid) => {

    const county = dataElection.find((item) => {
      const paddedCountyFips = item.county_fips.toString().padStart(5, '0')
      return paddedCountyFips === geoid
    })

    if (county) {
      return {
        colorData: parseFloat(county.vote_per_D) || 0,
        vote_per_D: county.vote_per_D,
        vote_per_R: county.vote_per_R,
        loc_pct_served: parseFloat(county.loc_pct_served) || 0
      }
    }
    return null
  }, [dataElection])

  const [hoveredPoint, setHoveredPoint] = useState(null);
  const onHover = useCallback((event) => {
    const county = event.features && event.features[0];
    if (county) {
      setHoveredPoint({
        ...county.properties,
        longitude: event.lngLat.lng,
        latitude: event.lngLat.lat,
      });
    } else {
      setHoveredPoint(null);
    }
  }, []);

  const onClick = useCallback((event) => {
    const features = event.target.queryRenderedFeatures(event.point);

    if (event?.features?.length > 0) {
      // console.log(event, features);
    }
  }, []);



  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await fetch(process.env.PUBLIC_URL + '/static/dataDummyReady/underserved_locations.geojson');
        if (!response.ok) {
          throw new Error('Failed to load GeoJSON data');
        }

        const geojsonData = await response.json();
        setDataPoint(geojsonData);
      } catch (error) {
        console.error('Error fetching GeoJSON:', error);
      }
    };

    fetchData();
  }, []);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await fetch(process.env.PUBLIC_URL + '/static/data/us_counties.geojson');
        if (!response.ok) {
          throw new Error('Failed to load GeoJSON data');
        }

        const geojsonData = await response.json();
        setDataPolygon(geojsonData);
      } catch (error) {
        console.error('Error fetching GeoJSON:', error);
      }
    };

    fetchData();
  }, []);

  const [dataPoint, setDataPoint] = useState({
    type: 'FeatureCollection',
    features: [],
  });
  const layerIDPoint = 'my-layer-circle';
  const layerStylePointCircle: any = {
    id: layerIDPoint,
    type: 'circle',
    paint: {
      'circle-radius': 6,
      'circle-color': '#4E3FC8',
      'circle-opacity': 0.8,
      'circle-stroke-width': 2,
      'circle-stroke-color': '#fff',
    },
  };


  const decayFactor = 1.5;

  const [dataPolygon, setDataPolygon] = useState({
    type: 'FeatureCollection',
    features: [],
  });
  const layerIDPolygon = 'polygon-layer';
  const layerStylePolygon: any = {
    id: layerIDPolygon,
    type: 'fill',
    paint: {
      // 'fill-color': '#f00',
      'fill-color': [
        'rgba',
        ['get', 'R'],
        ['get', 'G'],
        ['get', 'B'],
        ['get', 'O']
      ],
      'fill-opacity': 0.5,
      'fill-outline-color': '#000',
    },
  };
  const updatedGeoJSON = useMemo(
    () => ({
      ...dataPolygon,
      features: dataPolygon.features.map((feature) => {
        const county = getLocPctServed(feature.properties.GEOID)
        if (!county) return feature

        const voteR = parseFloat(county.vote_per_R)
        const voteD = parseFloat(county.vote_per_D)
        const sum = voteR + voteD
        const percentageD = voteD / sum
        const color = interpolateColor(percentageD)

        return {
          ...feature,
          properties: {
            ...feature.properties,
            R: color[0],
            G: 0,
            B: color[2],
            O:
              1 -
              Math.min(county.loc_pct_served ** 2 * decayFactor * 0.0001, 1),
            loc_pct_served: county.loc_pct_served,
            vote_per_D: county.vote_per_D,
            vote_per_R: county.vote_per_R
          }
        }
      })
    }),
    [dataPolygon, getLocPctServed, interpolateColor, decayFactor]
  )
  

  return (
    // <div ref={mapContainer} className={styles.mapContainer}>
    // <div>
    <div className={styles.mapContainer}>
      <div className={styles.menu}>
        <Controller mapRef={mapRef.current} />
      </div>
      <Suspense>
        <Map
          // @ts-ignore
          id={'mapbox-map'}
          mapLib={mapboxgl}
          ref={mapRef}
          initialViewState={{
            longitude: -100,
            latitude: 40,
            zoom: 3.5,
            // latitude: 37.7577,
            // longitude: -122.4376,
            // zoom: 8,
          }}
          style={{
            width: '100%',
            height: '100%',
            position: 'relative',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            zIndex: 0,
            flex: 1,
          }}
          mapStyle='mapbox://styles/mapbox/dark-v10'
          mapboxAccessToken={import.meta.env.VITE_MAPBOX}
          dragRotate={false}
          interactiveLayerIds={[
            layerIDPoint, 
            // layerIDPolygon
          ]}
          onMouseMove={onHover}
          onClick={onClick}
          // onMove={(evt) => setViewport(evt.viewState)}
          
        >
          <NavigationControl />
          <Source id={layerIDPoint} type='geojson' data={dataPoint}>
            <Layer {...layerStylePointCircle} />
          </Source>

          <Source id={layerIDPolygon} type='geojson' data={updatedGeoJSON}>
            <Layer {...layerStylePolygon} />
          </Source>

          {hoveredPoint && (
            <Popup
              longitude={hoveredPoint.longitude}
              latitude={hoveredPoint.latitude}
              offset={[0, -15]}
              closeButton={false}
              className='z-10'
            >
              <div className='p-2'>
                <h3 className='font-bold'>{hoveredPoint.NAME}</h3>
                <p>GEOID: { JSON.stringify(hoveredPoint)}</p>
              </div>
            </Popup>
          )}
          <div style={{
            position: 'absolute',
            background: 'rgba(255, 255, 255, 0.23)',
            width: '200px',
            height: '100px'
          }}>
          <BInterpolation />
          </div>

        </Map>
      </Suspense>
    </div>
  );
};
export default App;
