import { remap } from '../../../../../lib';
import { useRef, useState, useEffect } from 'react';

import { BezierInterpolation } from './BezierInterpolation';

const BInterpolation = () => {
	const canvasRef = useRef<HTMLCanvasElement>(null);
	const [isDragging, setIsDragging] = useState(false);
	const [startPos, setStartPos] = useState<{ x: number; y: number } | null>(null);

	const [bezierInterpolation] = useState(() => new BezierInterpolation(100));

	useEffect(() => {
		const canvas = canvasRef.current;
		if (!canvas) return;

		canvas.width = 500;
		canvas.height = 500;

		const ctx = canvas.getContext('2d');
		if (!ctx) return;

		ctx.fillStyle = 'white';
		ctx.fillRect(0, 0, canvas.width, canvas.height);

		bezierInterpolation.render(ctx);
	}, [bezierInterpolation]);

	const handleMouseDown = (e: React.MouseEvent<HTMLCanvasElement>) => {
		setIsDragging(true);
		const rect = canvasRef.current?.getBoundingClientRect();
		if (rect) {
			setStartPos({ x: e.clientX - rect.left, y: e.clientY - rect.top });

			const x = e.clientX - rect.left;
			const y = e.clientY - rect.top;

			bezierInterpolation.mouseDown(x, y);
		}
	};

	const handleMouseMove = (e: React.MouseEvent<HTMLCanvasElement>) => {
		if (!isDragging || !startPos) return;

		const canvas = canvasRef.current;
		const ctx = canvas?.getContext('2d');
		const rect = canvas?.getBoundingClientRect();

		if (ctx && rect) {
			//     console.log('dragging')
			const x = e.clientX - rect.left;
			const y = e.clientY - rect.top;

			//   ctx.strokeStyle = 'black';
			//   ctx.lineWidth = 2;
			//   ctx.beginPath();
			//   ctx.moveTo(startPos.x, startPos.y);
			//   ctx.lineTo(x, y);
			//   ctx.stroke();

			// console.log('ren')
			//   setStartPos({ x, y });

			bezierInterpolation.mouseDrag(x, y);
			bezierInterpolation.render(ctx);
			//   console.log(bezierInterpolation.getProjection());
		}
	};

	const handleMouseUp = () => {
		setIsDragging(false);
		setStartPos(null);
		bezierInterpolation.mouseUp(0, 0);
	};

	return (
		<canvas
			ref={canvasRef}
			width={500}
			height={500}
			onMouseDown={handleMouseDown}
			onMouseMove={handleMouseMove}
			onMouseUp={handleMouseUp}
			onMouseLeave={handleMouseUp} // 드래그 종료 처리
			style={{
				cursor: 'crosshair',
			}}
		/>
	);
};
export default BInterpolation;
